data.query:
query GetOeeData(
  $oeeWhere: OeeHourlyWhereInput
  $oeeOrderBy: [OeeHourlyOrderByInput!]
  $oeeFirst: Int
  $oeeAfter: String
  $productWhere: ProductWhereInput
  $productOrderBy: [ProductOrderByInput!]
  $productFirst: Int
  $productAfter: String
) {
  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        defaultValue
      }
    }
  }
  
  oeeHourly(where: $oeeWhere, orderBy: $oeeOrderBy, first: $oeeFirst, after: $oeeAfter) {
    edges {
      node {
        id
        goodUnits
        idealUnits
        performance
        quality
        scheduleHourStartAt
        scheduleHourEndAt
        scrapUnits
        totalUnits
        scheduleId
        actualCycleTime (format: milliseconds)
        idealCycleTime (format: milliseconds)
        workcenterId
      }
    }
  }
  
  product(where: $productWhere, orderBy: $productOrderBy, first: $productFirst, after: $productAfter) {
    edges {
      node {
        standardCycleTime 
        unitId
        idealCycleTime
      }
    }
  }
}

data.transform:
// Extract production log data
const productionLog = ($.value && $.value.after) || ($state.context && $state.context.afterData) || null;

if (!productionLog || !productionLog.workcenterId) {
  throw new Error('Production log data not found. Check data flow configuration.');
}

// Helper: convert duration field to milliseconds
// Handles both numeric (already ms) and string (ISO 8601 like "PT8H") formats
function toMs(val) {
  if (!val) return 0;
  if (typeof val === 'number') return val;
  if (typeof val === 'string') {
    try {
      return moment.duration(val).asMilliseconds();
    } catch (e) {
      console.log('Warning: Could not parse duration string: ' + val);
      return 0;
    }
  }
  return 0;
}

// Check if oeeHourly record exists for this time window
const oeeRecordExists = $.oeeHourly.edges && $.oeeHourly.edges.length > 0;
if (!oeeRecordExists) {
  console.log('No matching oeeHourly record found for occurAt: ' + productionLog.occurAt + ' on workcenter: ' + productionLog.workcenterId);
  console.log('Skipping processing - productionLog will not be marked as processed');
  return { skip: true };
}

// Extract data from query results
const oeeRecord = $.oeeHourly.edges[0].node;
const product = $.product.edges[0]?.node || {};

console.log('Processing production log for ' + productionLog.workcenterId);
console.log('OccurAt: ' + productionLog.occurAt);
console.log('Existing OEE record:', oeeRecord);
console.log('Product:', product);

// Product cycle times - DIFFERENT FORMATS:
// - product.idealCycleTime is a Duration field (returns milliseconds)
// - product.standardCycleTime is stored in seconds
// Both represent "seconds per unit" - normalize to seconds for calculation
const productIdealCycleTimeSec = product.idealCycleTime 
  ? toMs(product.idealCycleTime) / 1000   // Duration → ms → seconds
  : (product.standardCycleTime || 0);      // Already in seconds
const hasValidIdealCycleTime = productIdealCycleTimeSec > 0;

if (!hasValidIdealCycleTime) {
  console.log('WARNING: Product has no idealCycleTime or standardCycleTime defined. Ideal metrics will not be calculated.');
} else {
  console.log('Product cycle time raw values - idealCycleTime: ' + product.idealCycleTime + ' (Duration/ms), standardCycleTime: ' + product.standardCycleTime + ' (seconds)');
}

// Get existing values from oeeHourly
// Duration fields (actualCycleTime, idealCycleTime) are in MILLISECONDS - convert to seconds for calculation
const existingGoodUnits = oeeRecord.goodUnits || 0;
const existingScrapUnits = oeeRecord.scrapUnits || 0;
const existingTotalUnits = oeeRecord.totalUnits || 0;
const existingActualCycleTimeSec = toMs(oeeRecord.actualCycleTime) / 1000;
const existingIdealCycleTimeSec = toMs(oeeRecord.idealCycleTime) / 1000;
const existingIdealUnits = oeeRecord.idealUnits || 0;

// Get new production data from productionLog
// productionLog.cycleTime is in SECONDS for the total batch (e.g., 1800 = 1800 seconds for all units)
const newGoodQty = productionLog.quantityGood || 0;
const newScrapQty = productionLog.quantityScrap || 0;
const newTotalQty = newGoodQty + newScrapQty;
const newActualCycleTimeSec = productionLog.cycleTime || 0;

// Calculate incremental ideal values for this production log
// idealCycleTime increment = productIdealCycleTime × units produced (how long SHOULD it have taken)
// idealUnits increment = actualCycleTime / productIdealCycleTime (how many units SHOULD we have made)
const newIdealCycleTimeSecIncrement = hasValidIdealCycleTime ? (productIdealCycleTimeSec * newTotalQty) : 0;
const newIdealUnitsIncrement = hasValidIdealCycleTime ? (newActualCycleTimeSec / productIdealCycleTimeSec) : 0;

// Calculate new cumulative totals (in seconds)
const newGoodUnits = existingGoodUnits + newGoodQty;
const newScrapUnits = existingScrapUnits + newScrapQty;
const newTotalUnits = existingTotalUnits + newTotalQty;
const newActualCycleTimeSecTotal = existingActualCycleTimeSec + newActualCycleTimeSec;
const newIdealCycleTimeSecTotal = existingIdealCycleTimeSec + newIdealCycleTimeSecIncrement;
const newIdealUnitsTotal = existingIdealUnits + newIdealUnitsIncrement;

// Recalculate KPIs per ISO 22400 using cumulative values
// Quality = Good Units / Total Units
const quality = newTotalUnits > 0 ? newGoodUnits / newTotalUnits : 0;

// Performance = Ideal Cycle Time / Actual Cycle Time (capped at 1.0)
const performance = newActualCycleTimeSecTotal > 0 ? Math.min(newIdealCycleTimeSecTotal / newActualCycleTimeSecTotal, 1) : 0;

// Build update payload - Duration fields converted to MILLISECONDS for storage
const updatePayload = {
  id: oeeRecord.id,
  goodUnits: newGoodUnits,
  scrapUnits: newScrapUnits,
  totalUnits: newTotalUnits,
  actualCycleTime: Math.round(newActualCycleTimeSecTotal * 1000),  // seconds → ms
  idealCycleTime: Math.round(newIdealCycleTimeSecTotal * 1000),    // seconds → ms
  idealUnits: Math.round(newIdealUnitsTotal * 100) / 100,
  quality: Math.round(quality * 10000) / 10000,
  performance: Math.round(performance * 10000) / 10000
};

console.log('=== Calculation Summary ===');
console.log('Product ideal cycle time per unit: ' + productIdealCycleTimeSec + 's (from ' + (product.idealCycleTime ? 'idealCycleTime' : 'standardCycleTime') + ')');
console.log('New production: Good=' + newGoodQty + ', Scrap=' + newScrapQty + ', Total=' + newTotalQty);
console.log('New actual cycle time (batch): ' + newActualCycleTimeSec + 's');
console.log('Ideal cycle time increment: ' + newIdealCycleTimeSecIncrement + 's');
console.log('Ideal units increment: ' + newIdealUnitsIncrement.toFixed(2));
console.log('--- Cumulative Totals ---');
console.log('Total units: ' + newTotalUnits + ' (Good: ' + newGoodUnits + ', Scrap: ' + newScrapUnits + ')');
console.log('Actual cycle time: ' + newActualCycleTimeSecTotal + 's (' + (newActualCycleTimeSecTotal/60).toFixed(2) + ' min)');
console.log('Ideal cycle time: ' + newIdealCycleTimeSecTotal + 's (' + (newIdealCycleTimeSecTotal/60).toFixed(2) + ' min)');
console.log('Ideal units: ' + newIdealUnitsTotal.toFixed(2));
console.log('Quality: ' + (quality * 100).toFixed(2) + '%');
console.log('Performance: ' + (performance * 100).toFixed(2) + '%');

return updatePayload;

